/* ============================================================
   Design System — 作品集视觉设计规范
   风格：Apple 官网式「画廊」——近隐形 UI + 明暗瓦片交替
   配色：白 / 羊皮纸 / 近黑瓦片 + 单一 Action Blue 交互色
   排版：SF Pro 系统字体栈，展示级 600 字重紧字距，正文 17px
   支持：自动深色模式（跟随系统）

   响应式断点规范（改组件媒体查询时与这些档位保持一致）：
     640px —— 手机：汉堡菜单、单列内容
     768px —— 平板：作品瓦片单列、作品网格切换单列
     1024px —— 屏幕较宽/平板横屏：关于区切换单列

   组件库（全局类，组件内复用，避免重复定义）：
     .eyebrow   小节标签：12px 灰、首屏头衔 / 分区编号
     .tag       小标签（胶囊 14px + 发丝线）：类别、年份、详情页标签
     .btn       按钮：.btn-primary（蓝底白字）/ .btn-outline（白底蓝字描边）
     .text-link 文本链接：Action Blue，hover 下划线（Apple 式）
     .tile-dark / .tile-dark-2 / .tile-light
                全宽明暗瓦片：色块切换本身即分区，瓦片内 accent 自动换 Sky Blue
   ============================================================ */

:root {
  color-scheme: light dark; /* 让滚动条 / 表单控件跟随深色模式 */

  /* --- 色彩 Tokens（Apple Design） --- */
  --bg: #ffffff;               /* 画布白 canvas */
  --surface: #f5f5f7;          /* 羊皮纸 parchment：瓦片 / 页脚 / 弱卡片 */
  --surface-muted: #f0f0f2;    /* 珍珠白 pearl：标签底 / 占位 */
  --text: #1d1d1f;             /* 墨色 ink：全部正文与标题 */
  --text-secondary: #6e6e73;   /* 次级文字（白底 ≥4.5:1） */
  --text-tertiary: #86868b;    /* 弱文字：大号说明 / 禁用（白底 12px 慎用） */
  --on-inverse: #f5f5f7;       /* 深色瓦片上的主文字 */
  --on-inverse-muted: #a1a1a6; /* 深色瓦片上的次级文字 */
  --accent: #0066cc;           /* Action Blue：唯一交互色 */
  --accent-strong: #0071e3;    /* Focus Blue：hover / 焦点 */
  --accent-on-dark: #2997ff;   /* Sky Link Blue：深色面上的链接与强调 */
  --accent-soft: #e8f0fa;      /* 强调色浅底（正文引用） */
  --border: #e8e8ed;           /* 发丝线 hairline（浅背景） */
  --border-inverse: rgb(255 255 255 / 0.16); /* 深色面上的发丝线 */

  /* 明暗瓦片（Apple 节奏：色块切换本身即分隔线） */
  --tile-dark: #1d1d1f;
  --tile-dark-2: #272729;
  --tile-void: #000000;
  --glyph-on-inverse: rgb(255 255 255 / 0.08); /* 深色面幽灵图形 */

  /* --- 阴影：仅作品视觉留一处，UI chrome 无阴影 --- */
  --shadow-product: 0 4px 14px rgb(0 0 0 / 0.12);

  /* --- 圆角（Apple 语法：胶囊 / 18px 卡片 / 11px 珍珠钮 / 8px 小工具） --- */
  --radius-sm: 8px;
  --radius-md: 11px;
  --radius-lg: 18px;
  --radius-pill: 999px;

  /* --- 字体（SF Pro 系统栈，非 Apple 平台回退 PingFang / 微软雅黑） --- */
  --font-sans: -apple-system, BlinkMacSystemFont, "SF Pro Text",
    "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", "Helvetica Neue", sans-serif;
  --font-mono: ui-monospace, "SF Mono", "JetBrains Mono", Menlo, Consolas, monospace;

  /* --- 字号阶梯（Apple：17px 正文 / 14px 说明 / 12px 注释 / 21px 标语） --- */
  --text-xs: 12px;
  --text-sm: 14px;
  --text-md: 17px;
  --text-lg: 21px;

  /* --- 布局 --- */
  --container: 1120px;
  --gutter: clamp(20px, 5vw, 48px);
  --space-section: clamp(80px, 10vw, 120px);
  --header-h: 48px;

  /* --- 动效（按压反馈用缩放，苹果式） --- */
  --ease: cubic-bezier(0.4, 0, 0.2, 1);
  --dur: 0.24s;
  --dur-fast: 0.12s;
  --dur-slow: 0.6s;
}

/* --- 深色模式（整体映射 Apple 深色面） --- */
@media (prefers-color-scheme: dark) {
